-- PASSO 5 - Preenche/atualiza 99 resoluções de Contabilidade de Custos.
BEGIN;
UPDATE questoes SET resolution='{"regra": "No custeio baseado em atividades (ABC), os custos indiretos são atribuídos às atividades e, depois, aos produtos conforme o consumo dos direcionadores.", "passos": ["O enunciado informa três atividades e seus custos indiretos: R$ 14.000, R$ 24.000 e R$ 30.000.", "Cada custo deve ser rateado entre Alfa e Beta pelo respectivo direcionador de atividade.", "Depois de alocados os R$ 68.000 de custos indiretos, soma-se a parcela atribuída a cada produto ao custo direto unitário.", "O gabarito registrado no caderno é a alternativa C."], "calculo": "A extração textual do quadro não preserva de forma confiável todos os pares de direcionadores Alfa/Beta da tabela; por isso, não é possível reproduzir a conta completa com segurança apenas a partir do texto extraído.", "correta": "C — R$ 220,50 para Alfa e R$ 359,00 para Beta, conforme o gabarito do caderno.", "erradas": ["A) Considera apenas os custos diretos unitários, sem apropriar os custos indiretos.", "B) e D) apresentam outras combinações de custo unitário que não correspondem ao gabarito registrado."], "fundamento": "Custeio Baseado em Atividades (ABC): apropriação dos custos das atividades aos produtos por direcionadores de custos.", "pegadinha": "Não basta dividir os R$ 68.000 igualmente ou pela quantidade produzida; no ABC, cada atividade possui seu próprio direcionador.", "cobranca": "Contabilidade de Custos — ABC."}'::jsonb WHERE id='2746476';
UPDATE questoes SET resolution='{"regra": "No custeio por absorção, os custos indiretos de fabricação são incorporados ao custo dos produtos por um critério de rateio; aqui, o critério informado é a quantidade produzida e acabada.", "passos": ["Custo direto unitário de A: R$ 160.000 / 1.500 = R$ 106,67.", "Custo direto unitário de B: R$ 240.000 / 3.200 = R$ 75,00.", "Produção total: 1.500 + 3.200 = 4.700 unidades.", "CIF de A: R$ 120.000 × 1.500/4.700 = R$ 38.297,87.", "CIF de B: R$ 120.000 × 3.200/4.700 = R$ 81.702,13.", "Custos unitários resultantes: A ≈ R$ 132,20 e B ≈ R$ 100,53."], "calculo": "A: (160.000 + 38.297,87)/1.500 = R$ 132,20. B: (240.000 + 81.702,13)/3.200 = R$ 100,53.", "correta": "⚠️ Inconsistência: esses valores não aparecem nas alternativas; o gabarito registrado é B. A conta, com os dados extraídos, não reproduz o gabarito.", "erradas": ["Nenhuma alternativa pode ser validada pelos números extraídos do enunciado."], "fundamento": "Custeio por absorção — rateio dos custos indiretos conforme o critério informado no enunciado.", "pegadinha": "Não ajustar artificialmente os números para coincidir com o gabarito quando o rateio informado não produz nenhuma alternativa.", "cobranca": "Contabilidade de Custos — rateio de custos indiretos."}'::jsonb WHERE id='2746478';
UPDATE questoes SET resolution='{"regra": "No custeio por absorção, os custos indiretos são rateados aos produtos. Como o critério é o custo direto total, cada produto recebe parcela proporcional ao seu custo direto.", "passos": ["Custos diretos: Alfa R$ 112.500; Beta R$ 337.500; total R$ 450.000.", "Alfa representa 112.500/450.000 = 25% do custo direto total.", "Beta representa 337.500/450.000 = 75%.", "Dos R$ 200.000 de custos indiretos, Alfa recebe R$ 50.000 e Beta R$ 150.000.", "Custo total Alfa = R$ 162.500; dividido por 500 unidades = R$ 325.", "Custo total Beta = R$ 487.500; dividido por 1.250 unidades = R$ 390."], "calculo": "Alfa: (112.500 + 50.000)/500 = R$ 325,00. Beta: (337.500 + 150.000)/1.250 = R$ 390,00.", "correta": "D — R$ 325,00 e R$ 390,00.", "erradas": ["A) Usa rateio incompatível com o critério informado.", "B) Desconsidera parte relevante dos custos diretos/indiretos.", "C) e E) não resultam do rateio proporcional ao custo direto."], "fundamento": "Custeio por absorção — apropriação dos custos indiretos conforme critério de rateio definido.", "pegadinha": "Primeiro encontre a proporção dos custos diretos; só depois aplique essa proporção ao total dos custos indiretos.", "cobranca": "Contabilidade de Custos — custeio por absorção."}'::jsonb WHERE id='2153441';
UPDATE questoes SET resolution='{"regra": "CPP é a soma dos custos incorridos no período; CPA é o custo da produção acabada no período; CPV é o custo dos produtos vendidos.", "passos": ["A primeira definição fala dos custos incorridos dentro da fábrica no período: CPP.", "A segunda fala do custo dos produtos cuja fabricação foi concluída no período: CPA.", "A terceira fala dos custos dos produtos efetivamente vendidos: CPV."], "calculo": "Não há cálculo.", "correta": "E — Custo de Produção do Período (CPP); Custo da Produção Acabada (CPA); Custo dos Produtos Vendidos (CPV).", "erradas": ["A) Troca a ordem das três definições.", "B) Coloca CPV na segunda definição.", "C) Inverte CPP e CPA.", "D) Coloca CPV na segunda definição e CPP na terceira."], "fundamento": "Terminologia clássica de custos: CPP, CPA e CPV.", "pegadinha": "Produção acabada não significa necessariamente produto vendido; CPV depende da venda.", "cobranca": "Contabilidade de Custos — conceitos de produção e venda."}'::jsonb WHERE id='2431134';
UPDATE questoes SET resolution='{"regra": "No custeio por absorção, os custos indiretos são rateados proporcionalmente aos custos diretos totais quando esse é o critério indicado.", "passos": ["Custos diretos Alfa = 55.000 + 89.000 = R$ 144.000.", "Custos diretos Beta = 75.000 + 101.000 = R$ 176.000.", "Total de custos diretos = R$ 320.000.", "Custos indiretos = 24.000 + 36.000 + 12.000 = R$ 72.000.", "Alfa recebe 144/320 dos CIF = R$ 32.400. Beta recebe 176/320 = R$ 39.600.", "Custo total Alfa = R$ 176.400; /1.200 = R$ 147. Beta = R$ 215.600; /1.400 = R$ 154."], "calculo": "Alfa: (144.000 + 32.400)/1.200 = R$ 147,00. Beta: (176.000 + 39.600)/1.400 = R$ 154,00.", "correta": "B — R$ 147,00 e R$ 154,00.", "erradas": ["A) Não incorpora corretamente os custos indiretos.", "C) Superestima os custos unitários.", "D) Usa rateio incompatível com o critério informado."], "fundamento": "Custeio por absorção e rateio dos custos indiretos pelo custo direto total.", "pegadinha": "Some todos os custos indiretos antes de calcular a proporção de rateio.", "cobranca": "Contabilidade de Custos — custeio por absorção."}'::jsonb WHERE id='2431265';
UPDATE questoes SET resolution='{"regra": "Os R$ 80.000 de custos indiretos são rateados pela quantidade produzida: 800 unidades de A e 1.200 de B, total de 2.000.", "passos": ["A recebe 80.000 × 800/2.000 = R$ 32.000 de CIF.", "B recebe 80.000 × 1.200/2.000 = R$ 48.000.", "Custo total A = 120.000 + 32.000 = R$ 152.000; /800 = R$ 190.", "Custo total B = 360.000 + 48.000 = R$ 408.000; /1.200 = R$ 340."], "calculo": "A = R$ 190,00/unidade; B = R$ 340,00/unidade.", "correta": "B — R$ 190,00 e R$ 340,00.", "erradas": ["A) Considera apenas os custos diretos unitários.", "C) Não corresponde ao rateio dos CIF pela quantidade.", "D) e E) apresentam rateios diferentes do critério indicado."], "fundamento": "Custeio por absorção — rateio dos custos indiretos pela quantidade produzida.", "pegadinha": "A proporção deve ser aplicada ao CIF total antes de chegar ao custo unitário.", "cobranca": "Contabilidade de Custos — rateio por quantidade."}'::jsonb WHERE id='1741091';
UPDATE questoes SET resolution='{"regra": "Os custos indiretos são rateados pela quantidade produzida: 300 unidades de A e 700 de B.", "passos": ["Custos diretos A = 54.000 + 33.000 = R$ 87.000.", "Custos diretos B = 77.000 + 21.000 = R$ 98.000.", "CIF total = 32.000 + 25.000 + 16.000 = R$ 73.000.", "A recebe 73.000 × 300/1.000 = R$ 21.900; custo total = R$ 108.900; /300 = R$ 363.", "B recebe R$ 51.100; custo total = R$ 149.100; /700 = R$ 213."], "calculo": "A = (87.000 + 21.900)/300 = R$ 363,00. B = (98.000 + 51.100)/700 = R$ 213,00.", "correta": "E — R$ 363,00 e R$ 213,00.", "erradas": ["A) e B) não incorporam corretamente os CIF.", "C) e D) apresentam valores incompatíveis com o rateio pela quantidade."], "fundamento": "Custeio por absorção — apropriação dos custos indiretos conforme quantidade produzida.", "pegadinha": "Não rateie cada custo indireto separadamente por um critério diferente; o enunciado determina um único critério.", "cobranca": "Contabilidade de Custos — custeio por absorção."}'::jsonb WHERE id='2165652';
UPDATE questoes SET resolution='{"regra": "Os custos indiretos são rateados pela quantidade produzida: 300 unidades de Alfa e 900 de Beta.", "passos": ["Custos diretos Alfa = R$ 250.000; Beta = R$ 300.000.", "CIF total = R$ 80.000.", "Alfa recebe 80.000 × 300/1.200 = R$ 20.000.", "Beta recebe 80.000 × 900/1.200 = R$ 60.000.", "Custo total Alfa = R$ 270.000; /300 = R$ 900.", "Custo total Beta = R$ 360.000; /900 = R$ 400."], "calculo": "Alfa: (250.000 + 20.000)/300 = R$ 900,00. Beta: (300.000 + 60.000)/900 = R$ 400,00.", "correta": "A — R$ 900,00 e R$ 400,00.", "erradas": ["B) e C) não correspondem ao rateio dos R$ 80.000 pela quantidade produzida.", "D) também não reproduz o cálculo."], "fundamento": "Custeio por absorção — rateio dos custos indiretos pela quantidade produzida e acabada.", "pegadinha": "O CIF de Alfa é R$ 20 mil, não R$ 80 mil; o restante é atribuído a Beta pela proporção 300:900.", "cobranca": "Contabilidade de Custos — rateio por quantidade."}'::jsonb WHERE id='1972618';
UPDATE questoes SET resolution='{"regra": "No custeio por absorção, custos fixos e variáveis, diretos e indiretos de produção são apropriados aos produtos; os indiretos exigem critério de rateio quando necessário.", "passos": ["A, B e D descrevem características do custeio por absorção.", "A alternativa C afirma que os resultados não sofrem influência direta do volume de produção.", "Essa afirmação é incorreta: no custeio por absorção, custos fixos de produção são incorporados aos produtos, e o volume produzido pode afetar o custo unitário e o resultado."], "calculo": "Não há cálculo.", "correta": "C — é a exceção.", "erradas": ["A) Está de acordo com a absorção dos custos de produção.", "B) Está de acordo com a necessidade de rateio dos custos indiretos.", "D) Corresponde à ideia de custeio integral dos gastos de fabricação."], "fundamento": "Conceito de custeio por absorção.", "pegadinha": "Não confunda custeio por absorção com custeio variável; o tratamento dos custos fixos de fabricação é diferente.", "cobranca": "Contabilidade de Custos — características do custeio por absorção."}'::jsonb WHERE id='1030086';
UPDATE questoes SET resolution='{"regra": "Os R$ 50.000 de custos indiretos são rateados pela quantidade produzida: 350 unidades de Alfa e 650 de Omega.", "passos": ["Custos diretos Alfa = R$ 85.750; Omega = R$ 93.600.", "Produção total = 1.000 unidades.", "CIF Alfa = 50.000 × 350/1.000 = R$ 17.500.", "CIF Omega = 50.000 × 650/1.000 = R$ 32.500.", "Custo unitário Alfa = (85.750 + 17.500)/350 = R$ 295.", "Custo unitário Omega = (93.600 + 32.500)/650 = R$ 194."], "calculo": "Alfa = R$ 295,00/unidade. Omega = R$ 194,00/unidade.", "correta": "E — R$ 295,00 e R$ 194,00.", "erradas": ["A) e B) invertem ou não reproduzem os custos calculados.", "C) e D) não resultam do rateio dos CIF pela quantidade."], "fundamento": "Custeio por absorção — rateio dos custos indiretos pela quantidade produzida.", "pegadinha": "O produto com mais unidades recebe parcela maior dos CIF, mas o custo unitário final depende também do custo direto unitário.", "cobranca": "Contabilidade de Custos — custeio por absorção."}'::jsonb WHERE id='1335877';
UPDATE questoes SET resolution='{"regra": "No custeio por absorção, o custo de produção inclui os custos de fabricação, fixos e variáveis, diretos e indiretos; despesas de venda e administrativas não entram no custo de produção.", "passos": ["Custo fixo de produção = R$ 20.000.", "Custos variáveis de produção = (12 + 6) × 500 = R$ 9.000.", "Custo total da produção = 20.000 + 9.000 = R$ 29.000.", "Dividindo pelas 500 unidades produzidas: R$ 29.000/500 = R$ 58,00."], "calculo": "R$ 20.000 + (R$ 12 × 500) + (R$ 6 × 500) = R$ 29.000; R$ 29.000/500 = R$ 58,00.", "correta": "A — R$ 58,00.", "erradas": ["B) e C) incluem valores que não compõem o custo unitário de produção.", "D) e E) incorporam despesas/fretes/comissões ou outros gastos de venda que não são custos de fabricação."], "fundamento": "Custeio por absorção — apropriação dos custos de produção aos produtos.", "pegadinha": "Frete sobre vendas, comissões e despesas fixas administrativas são despesas, não custos de produção.", "cobranca": "Contabilidade de Custos — formação do custo unitário."}'::jsonb WHERE id='1336852';
UPDATE questoes SET resolution='{"regra": "O lucro líquido é obtido a partir da receita líquida menos o custo dos produtos vendidos e as despesas do período. A questão usa os mesmos dados da Q25.", "passos": ["Receita bruta = 400 × R$ 250 = R$ 100.000.", "Desconto condicional concedido = R$ 5.000; receita líquida = R$ 95.000.", "Custo unitário de produção, pela Q25, = R$ 58; CPV de 400 unidades = R$ 23.200.", "Comissões = 10% × R$ 100.000 = R$ 10.000.", "Frete sobre vendas = 400 × R$ 15 = R$ 6.000.", "Despesas fixas = R$ 6.000.", "Lucro = 95.000 − 23.200 − 10.000 − 6.000 − 6.000 = R$ 49.800."], "calculo": "R$ 95.000 − R$ 23.200 − R$ 10.000 − R$ 6.000 − R$ 6.000 = R$ 49.800.", "correta": "D — R$ 49.800,00.", "erradas": ["A) e B) não descontam corretamente todos os gastos do período.", "C) e E) resultam de combinações incorretas entre receita, CPV e despesas."], "fundamento": "Custeio por absorção e apuração do resultado do período.", "pegadinha": "O custo unitário de R$ 58 é aplicado às 400 unidades vendidas, não às 500 unidades produzidas, para obter o CPV.", "cobranca": "Contabilidade de Custos — apuração do lucro."}'::jsonb WHERE id='1336854';
UPDATE questoes SET resolution='{"regra": "No custeio por absorção, custos diretos e indiretos são incorporados ao custo dos serviços. O enunciado informa que o CIF de R$ 40.000 é rateado pelas horas-máquina.", "passos": ["Horas-máquina totais: 7.000 + 3.000 = 10.000 HM.", "Taxa de CIF por HM = R$ 40.000/10.000 = R$ 4,00 por HM.", "Para contêineres cheios: CIF por movimentação = R$ 4 × (7.000/14.000) = R$ 2,00.", "Para vazios: CIF por movimentação = R$ 4 × (3.000/12.000) = R$ 1,00.", "Somando aos custos variáveis literalmente apresentados como R$ 50/HM e R$ 30/HM, o cálculo não produz a alternativa D."], "calculo": "Pelos números visíveis no material: cheios = R$ 50,00 + R$ 2,00 = R$ 52,00; vazios = R$ 30,00 + R$ 1,00 = R$ 31,00. Esses valores não aparecem nas alternativas.", "correta": "⚠️ Inconsistência no material: o gabarito registrado é D (R$ 27,00 e R$ 8,50), mas os valores visíveis da tabela não permitem reproduzi-lo. Questão deve ser conferida na fonte original.", "erradas": ["A), B), C) e D) não podem ser validadas com os dados literalmente visíveis; D é apenas o gabarito registrado no caderno."], "fundamento": "Custeio por absorção e rateio dos custos indiretos pelas horas-máquina.", "pegadinha": "Questões com tabelas mal extraídas exigem conferência do original; não devemos ajustar artificialmente os custos para alcançar o gabarito.", "cobranca": "Contabilidade de Custos — custeio por absorção."}'::jsonb WHERE id='1058486';
UPDATE questoes SET resolution='{"regra": "No custeio por absorção, devem compor o custo dos serviços os gastos diretamente relacionados à prestação do serviço. A tabela informa quatro atividades por tonelada; os gastos adicionais incluem energia, guarda portuária e serviços administrativos.", "passos": ["Custo das atividades por tonelada = 0,25 + 0,10 + 0,25 + 1,50 = R$ 2,10 por tonelada.", "Para 27.000 toneladas: 27.000 × R$ 2,10 = R$ 56.700.", "Energia elétrica industrial: + R$ 16.200.", "Guarda portuária: + R$ 21.600.", "Serviços administrativos para gestão do trâmite aduaneiro são despesa administrativa e não custo de produção/serviço no custeio por absorção.", "Total de custos = 56.700 + 16.200 + 21.600 = R$ 94.500."], "calculo": "R$ 56.700 + R$ 16.200 + R$ 21.600 = R$ 94.500.", "correta": "C — R$ 94.500,00.", "erradas": ["A) Desconsidera parte dos custos.", "B) Não corresponde à soma dos custos de serviço.", "D) Inclui também os R$ 7.800 de serviços administrativos, tratados na questão como despesa administrativa."], "fundamento": "Custeio por absorção — distinção entre custos de produção/serviço e despesas administrativas.", "pegadinha": "Nem todo gasto da empresa é custo: serviços administrativos são despesas quando não integram a prestação do serviço.", "cobranca": "Contabilidade de Custos — custeio por absorção e distinção custo x despesa."}'::jsonb WHERE id='1058491';
UPDATE questoes SET resolution='{"regra": "No custeio por absorção, todos os custos de produção, fixos e variáveis, diretos e indiretos, são apropriados aos produtos.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custeio por Absorção: Caso Geral sem Departamentalização.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é B."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "B — R$ 109.400,00.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custeio por Absorção: Caso Geral sem Departamentalização"}'::jsonb WHERE id='1058495';
UPDATE questoes SET resolution='{"regra": "No custeio por absorção, todos os custos de produção, fixos e variáveis, diretos e indiretos, são apropriados aos produtos.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custeio por Absorção: Caso Geral sem Departamentalização.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é D."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "D — R$ 112.200,00", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custeio por Absorção: Caso Geral sem Departamentalização"}'::jsonb WHERE id='562906';
UPDATE questoes SET resolution='{"regra": "No custeio por absorção, todos os custos de produção, fixos e variáveis, diretos e indiretos, são apropriados aos produtos.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custeio por Absorção: Caso Geral sem Departamentalização.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é A."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "A — R$ 7.500,00", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custeio por Absorção: Caso Geral sem Departamentalização"}'::jsonb WHERE id='562910';
UPDATE questoes SET resolution='{"regra": "A resolução decorre da aplicação direta do conceito central cobrado no enunciado.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Ponto de Equilíbrio: Relação Custo/Volume/Resultado.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é C."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "C — Ponto de Equilíbrio.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Ponto de Equilíbrio: Relação Custo/Volume/Resultado"}'::jsonb WHERE id='1030084';
